131	<body>
132	    <div class="container">
133	        <h1><i class="fas fa-utensils"></i> Random Lunch Generator</h1>
134	        <p class="description">Struggling to decide what to eat? Let us choose for you with just one click!</p>
135	        
136	        <div class="lunch-display">
137	            <div class="food-icon"><i class="fas fa-question"></i></div>
138	            <div class="food-name">What's for lunch?</div>
139	        </div>
140	        
141	        <button class="generate-btn" id="generateBtn">
142	            <i class="fas fa-random"></i> Generate Lunch!
143	        </button>
144	        
145	        <p class="footer">Click the button again if you can't decide!</p>
146	    </div>
147	
148	    <script>
149	        document.addEventListener('DOMContentLoaded', function() {
150	            const generateBtn = document.getElementById('generateBtn');
151	            const foodIcon = document.querySelector('.food-icon');
152	            const foodName = document.querySelector('.food-name');
153	            const lunchDisplay = document.querySelector('.lunch-display');
154	            
155	            // Array of lunch options with corresponding Font Awesome icons
156	            const lunchMenu = [
157	                { name: "Pizza", icon: "fas fa-pizza-slice" },
158	                { name: "Sushi", icon: "fas fa-fish" },
159	                { name: "Burger", icon: "fas fa-hamburger" },
160	                { name: "Salad", icon: "fas fa-leaf" },
161	                { name: "Tacos", icon: "fas fa-utensil-spoon" },
162	                { name: "Ramen", icon: "fas fa-bowl-hot" },
163	                { name: "Sandwich", icon: "fas fa-bread-slice" },
164	                { name: "Pasta", icon: "fas fa-pasta" },
165	                { name: "Curry", icon: "fas fa-mortar-pestle" },
166	                { name: "Steak", icon: "fas fa-drumstick-bite" },
167	                { name: "Soup", icon: "fas fa-bowl" },
168	                { name: "BBQ", icon: "fas fa-fire" }
169	            ];
170	            
171	            // Function to generate random lunch
172	            function generateRandomLunch() {
173	                // Remove fade-in class if it exists
174	                lunchDisplay.classList.remove('fade-in');
175	                
176	                // Get a random lunch option
177	                const randomIndex = Math.floor(Math.random() * lunchMenu.length);
178	                const selectedLunch = lunchMenu[randomIndex];
179	                
180	                // Briefly show loading state
181	                foodIcon.innerHTML = '<i class="fas fa-spinner fa-spin"></i>';
182	                foodName.textContent = "Thinking...";
183	                
184	                // After a short delay, show the selected lunch
185	                setTimeout(() => {
186	                    foodIcon.innerHTML = `<i class="${selectedLunch.icon}"></i>`;
187	                    foodName.textContent = selectedLunch.name;
188	                    
189	                    // Add animation class
190	                    lunchDisplay.classList.add('fade-in');
191	                }, 500);
192	            }
193	            
194	            // Add click event to button
195	            generateBtn.addEventListener('click', generateRandomLunch);
196	            
197	            // Generate a random lunch on page load
198	            generateRandomLunch();
199	        });
200	    </script>
201	</body>
202	</html>

