+
+  <script>
+    (() => {
+      const root = document.getElementById("lunch-counts-by-index");
+      const chart = root.querySelector(".index-chart");
+      const data = [
+        { index: 0, name: "Pizza", count: 86 },
+        { index: 1, name: "Sushi", count: 104 },
+        { index: 2, name: "Burger", count: 84 },
+        { index: 3, name: "Salad", count: 87 },
+        { index: 4, name: "Tacos", count: 92 },
+        { index: 5, name: "Ramen", count: 105 },
+        { index: 6, name: "Sandwich", count: 86 },
