Compare the disclosure with the authentic session log and repository history. Confirm:

- all AI tools and uses are listed;
- no student action is claimed without confirmation;
- unverified AI output is disclosed honestly;
- durations, milestones, files, and tool usage do not contradict the log;
- a crashed or incomplete session is documented;
- the session export has not been edited, synthesized, shortened, or reformatted.

## Gate 0 stop conditions

Do not call the homework submission-ready when any of these remain:

- a cited reference is unverified, broken, fabricated, or misattributed;
- a reported number cannot be traced to current program output;
- the code or final pipeline does not run;
- a table or figure disagrees with the raw output;
- an API, function, tool version, or mechanism is asserted without verification;
- the reasoning gives a wrong or unsupported root cause;
- results were cherry-picked without disclosure;
- the report claims personal verification that the student did not perform;
- the AI disclosure contradicts the session log;
- the authentic session log is missing without an explicit, honest note and instructor coordination.

## Final manual review

After the automated preflight passes:

- render and inspect every PDF page;
- confirm the body is within the applicable page limit;
- remove unresolved placeholders and review markers;
- verify title-block identity and assignment ID;
- test every cited URL;
- compare every reported value against the final run;
- confirm the student has read and owns the first-person discussion and disclosure;
- preserve the original session export unchanged.

const fs = require("fs");
const path = require("path");
const vm = require("vm");

const numberOfClicks = 1000;
const counts = new Map();
let clickHandler;
let recordSelections = false;

const button = {
    addEventListener(eventName, handler) {
        if (eventName === "click") {
            clickHandler = handler;
        }
    },
};

const foodIcon = { innerHTML: "" };
const lunchDisplay = {
    classList: {
        add() {},
        remove() {},
    },
};
const foodName = {
    _textContent: "",
    get textContent() {
        return this._textContent;
    },
    set textContent(value) {
        this._textContent = value;
        if (recordSelections && value !== "Thinking...") {
            counts.set(value, (counts.get(value) || 0) + 1);
        }
    },
};

const document = {
    getElementById(id) {
        return id === "generateBtn" ? button : null;
    },
    querySelector(selector) {
        const elements = {
            ".food-icon": foodIcon,
            ".food-name": foodName,
            ".lunch-display": lunchDisplay,
        };
        return elements[selector] || null;
    },
};

const context = {
    document,
    Math,
    window: {
        setTimeout(callback) {
            callback();
        },
    },
};

const applicationCode = fs.readFileSync(path.join(__dirname, "script.js"), "utf8");
vm.runInNewContext(applicationCode, context, { filename: "script.js" });

if (typeof clickHandler !== "function") {
    throw new Error("The generator did not register its click handler.");
}

recordSelections = true;
for (let click = 0; click < numberOfClicks; click += 1) {
    clickHandler();
}

const distribution = [...counts.entries()]
    .map(([name, count]) => ({ name, count, percentage: count / 10 }))
    .sort((left, right) => right.count - left.count || left.name.localeCompare(right.name));
const observedTotal = distribution.reduce((total, item) => total + item.count, 0);

if (observedTotal !== numberOfClicks) {
    throw new Error(`Expected ${numberOfClicks} selections, observed ${observedTotal}.`);
}

console.log(JSON.stringify({ numberOfClicks, distribution }, null, 2));
import json
from pathlib import Path

from scipy.stats import chi2, chisquare


ALPHA = 0.05
DATA_PATH = Path(__file__).with_name("distribution-1000.json")


with DATA_PATH.open(encoding="utf-8") as input_file:
    experiment = json.load(input_file)

distribution = experiment["distribution"]
observed = [item["count"] for item in distribution]
number_of_categories = len(observed)
number_of_clicks = sum(observed)
expected_count = number_of_clicks / number_of_categories
expected = [expected_count] * number_of_categories

statistic, p_value = chisquare(f_obs=observed, f_exp=expected)
degrees_of_freedom = number_of_categories - 1
critical_value = chi2.ppf(1 - ALPHA, degrees_of_freedom)

contributions = [
    {
        "name": item["name"],
        "observed": item["count"],
        "expected": expected_count,
        "chi_square_contribution": (item["count"] - expected_count) ** 2 / expected_count,
    }
    for item in distribution
]

manual_statistic = sum(item["chi_square_contribution"] for item in contributions)
if abs(manual_statistic - statistic) > 1e-12:
    raise RuntimeError("Manual and SciPy chi-square statistics do not match.")

result = {
    "null_hypothesis": "Each of the 12 menu items has probability 1/12.",
    "alternative_hypothesis": "At least one menu-item probability differs from 1/12.",
    "alpha": ALPHA,
    "sample_size": number_of_clicks,
    "categories": number_of_categories,
    "expected_count_per_category": expected_count,
    "chi_square_statistic": statistic,
    "degrees_of_freedom": degrees_of_freedom,
    "p_value": p_value,
    "critical_value": critical_value,
    "decision": "reject H0" if p_value < ALPHA else "fail to reject H0",
    "contributions": sorted(
        contributions,
        key=lambda item: item["chi_square_contribution"],
        reverse=True,
    ),
}

print(json.dumps(result, indent=2))
