 12	function mulberry32(seed) {
 13	    let state = seed;
 14	    return function random() {
 15	        state |= 0;
 16	        state = (state + 0x6d2b79f5) | 0;
 17	        let value = Math.imul(state ^ (state >>> 15), 1 | state);
 18	        value = (value + Math.imul(value ^ (value >>> 7), 61 | value)) ^ value;
 19	        return ((value ^ (value >>> 14)) >>> 0) / 4294967296;
 20	    };
 21	}
 22	
 23	function directCounts() {
 24	    const random = mulberry32(SEED);
 25	    const counts = Array(menuNames.length).fill(0);
 26	
 27	    random(); // Match the application's automatic selection on page load.
 28	    for (let click = 0; click < NUMBER_OF_CLICKS; click += 1) {
 29	        const index = Math.floor(random() * menuNames.length);
